class GmailConnector:
    SCOPES = [
        'https://www.googleapis.com/auth/gmail.modify',
        'https://www.googleapis.com/auth/contacts.readonly'
    ]

    def __init__(self, config):
        creds = None
        creds_path = Path(__file__).parent / "credentials.json"
        token_path = Path(config.get("token_path", "./token.json"))
        if token_path.exists():
            creds = Credentials.from_authorized_user_file(str(token_path), GmailConnector.SCOPES)
        else:
            flow = InstalledAppFlow.from_client_secrets_file(
                str(creds_path),
                GmailConnector.SCOPES,
                redirect_uri='urn:ietf:wg:oauth:2.0:oob'
            )
            # Manual console-based authentication for headless environments
            auth_url, _ = flow.authorization_url(prompt='consent')
            print(f"🔗 Please go to this URL to authorize:\n{auth_url}")
            code = input("Enter the authorization code here: ")
            flow.fetch_token(code=code)
            creds = flow.credentials
            with open(token_path, "w") as token_file:
                token_file.write(creds.to_json())
        self.service = build('gmail', 'v1', credentials=creds)
        self.page_token = None

    def fetch_unread(self, max_results=10):
        params = {'userId': 'me', 'q': 'is:unread', 'maxResults': max_results}
        if self.page_token:
            params['pageToken'] = self.page_token
        results = self.service.users().messages().list(**params).execute()
        self.page_token = results.get('nextPageToken')
        msgs = results.get('messages', [])
        messages = []
        for m in msgs:
            msg = self.service.users().messages().get(userId='me', id=m['id'], format='full').execute()
            payload = msg.get('payload', {})
            headers = {h['name']: h['value'] for h in payload.get('headers', [])}
            body = ''
            if 'parts' in payload:
                for part in payload['parts']:
                    if part.get('mimeType') == 'text/plain':
                        data = part['body'].get('data', '')
                        body = base64.urlsafe_b64decode(data).decode('utf-8')
            messages.append({
                "id": m['id'],
                "from": headers.get('From',''),
                "subject": headers.get('Subject',''),
                "snippet": msg.get('snippet',''),
                "body": body
            })
        return messages

    def summarize(self, messages):
        summary = f"🔍 Total unread: {len(messages)}"
        senders = list({m['from'] for m in messages})
        return summary, senders

    def prepare_drafts(self, messages):
        drafts = []
        for m in messages:
            drafts.append({
                "to": m["from"],
                "subject": f"Re: {m['subject']}",
                "body": f"Hello,\n\nThanks for reaching out about \"{m['subject']}\". I'll get back to you shortly.\n\nBest,\n{config.get('name')}"
            })
        return drafts

    def archive(self, messages):
        count = 0
        for m in messages:
            self.service.users().messages().modify(
                userId='me', id=m['id'], body={'removeLabelIds': ['UNREAD']}
            ).execute()
            count += 1
        return f"🗄 Archived {count} messages."

    def send_email(self, to, subject, body):
        # Create MIME message
        msg = MIMEText(body)
        msg['to'] = to
        msg['subject'] = subject
        raw = base64.urlsafe_b64encode(msg.as_bytes()).decode()
        sent_msg = self.service.users().messages().send(
            userId='me',
            body={'raw': raw}
        ).execute()
        return sent_msg.get('id')

connector = GmailConnector(config)



def update_known_senders():
    known = set(config.get("known_senders", []))
    bad = set(config.get("bad_senders", []))
    # Exclude any blacklisted senders from known
    known -= bad
    initialized = config.get("known_senders_initialized", False)

    if not initialized:
        # Heavy initial load: Sent, Inbox, Contacts
        sent_results = connector.service.users().messages().list(
            userId='me', labelIds=['SENT'], maxResults=200
        ).execute().get('messages', [])
        sent_senders = []
        for m in sent_results:
            msg = connector.service.users().messages().get(
                userId='me', id=m['id'], format='metadata', metadataHeaders=['To','Cc']
            ).execute()
            hdrs = {h['name']:h['value'] for h in msg.get('payload',{}).get('headers',[])}
            for hdr in ('To','Cc'):
                if hdr in hdrs:
                    for addr in hdrs[hdr].split(','):
                        sent_senders.append(addr.strip())

        inbox_results = connector.service.users().messages().list(
            userId='me', labelIds=['INBOX'], q='-category:promotions -category:social', maxResults=200
        ).execute().get('messages', [])
        inbox_senders = []
        for m in inbox_results:
            msg = connector.service.users().messages().get(
                userId='me', id=m['id'], format='metadata', metadataHeaders=['From']
            ).execute()
            hdrs = {h['name']:h['value'] for h in msg.get('payload',{}).get('headers',[])}
            inbox_senders.append(hdrs.get('From','').strip())

        # Contacts via People API
        token_path = Path(config.get("token_path","./token.json"))
        creds = Credentials.from_authorized_user_file(str(token_path), GmailConnector.SCOPES)
        people_service = build('people','v1',credentials=creds)
        connections = people_service.people().connections().list(
            resourceName='people/me', pageSize=200, personFields='emailAddresses'
        ).execute().get('connections', [])
        contact_emails = [c['emailAddresses'][0]['value'] for c in connections if c.get('emailAddresses')]

        active_contacts = [c for c in contact_emails if c in set(sent_senders+inbox_senders) and c not in bad]
        if active_contacts:
            new_known = sorted([s for s in active_contacts[:10] if s])
        else:
            freq = Counter(sent_senders+inbox_senders)
            top = [s for s,_ in freq.most_common(10)]
            filtered = [s for s in set(top)|known if s]
            new_known = sorted(filtered)

        # Remove any blacklisted senders from the new list
        new_known = [s for s in new_known if s not in bad]

        config["known_senders"] = new_known
        config["known_senders_initialized"] = True
        print(Fore.GREEN + Style.BRIGHT + "✅ known_senders initialized:" + Style.RESET_ALL)
        for s in new_known:
            print("  " + Fore.YELLOW + s + Style.RESET_ALL)
    else:
        # Lightweight incremental check: only recent unread
        messages = connector.fetch_unread(max_results=50)
        incremental = [m["from"] for m in messages]
        new = [s for s in incremental if s and s not in known and s not in bad]
        if new:
            known.update(new)
            config["known_senders"] = sorted(known)
            print(Fore.CYAN + "🔄 Appended new known_senders:" + Style.RESET_ALL)
            for s in new:
                print("  " + Fore.YELLOW + s + Style.RESET_ALL)

    # Persist config
    with open(config_path, "w") as f:
        yaml.safe_dump(config, f)

# Run update on boot
update_known_senders()

