def show_senders_page():
    global senders_page
    known = config.get("known_senders", [])
    total = len(known)
    start = senders_page * senders_page_size
    end = min(start + senders_page_size, total)
    page = known[start:end]
    print(f"📬 Known senders {start+1}-{end} of {total}:")
    for idx, s in enumerate(page, start=1):
        print(f"{idx}. {s}")
    print("🧠 Commands: 'remove <n>', 'nextsenders', 'prevsenders', 'senders save', or 'exit'")


def run_command():
    # Declare globals for state variables
    global config, last_page, last_drafts, senders_page, current_important, current_page
    while True:
        task = input(f"🧠 {name} > ").strip()
        # Load known_senders from config at the top of each loop
        known = set(config.get("known_senders", []))
        if task.lower() in ["exit", "quit"]:
            break
        elif task == "fetch":
            # Fetch the next 10 unread messages
            page = connector.fetch_unread(max_results=10)
            last_page = page
            if not page:
                print("⚠️ No more unread messages.")
            else:
                print(f"📥 Fetched {len(page)} unread messages:")
                for i, m in enumerate(page, start=1):
                    print(f"{i}. From: {m['from']} | Subject: {m['subject']}")
            print("🧠 Use 'next' to fetch the next 10 emails or 'draft <n>' to draft.")
        elif task.lower() in ["next", "more"]:
            # Fetch the next 10 unread messages
            page = connector.fetch_unread(max_results=10)
            last_page = page
            if not page:
                print("⚠️ No more unread messages.")
            else:
                print(f"📥 Fetched next {len(page)} messages:")
                for i, m in enumerate(page, start=1):
                    print(f"{i}. From: {m['from']} | Subject: {m['subject']}")
            print("🧠 Use 'next' to fetch more, 'draft <n>' to draft, or 'exit'.")
        elif task.lower() in ["previous", "prev"]:
            # Show the initial batch again
            messages = connector.fetch_unread(max_results=page_size)
            known = set(config.get("known_senders", []))
            page = [
                m for m in messages
                if m["from"] in known
                and "no-reply" not in m["from"].lower()
                and "noreply" not in m["from"].lower()
            ]
            last_page = page
            print(f"📥 Reset to first batch: Showing {len(page)} important messages:")
            for i, m in enumerate(page, start=1):
                print(f"{i}. From: {m['from']}\n   Subject: {m['subject']}\n   Snippet: {m['snippet']}\n")
            print("🧠 Use 'next' to see next batch, 'previous' to return here, or 'draft <n>' to draft.")
        elif task.startswith("draft"):
            parts = task.split()
            if len(parts) != 2 or not parts[1].isdigit():
                print("⚠️ Usage: draft <n> where n is the message number on the current page.")
            else:
                idx = int(parts[1]) - 1
                try:
                    m = last_page[idx]
                except IndexError:
                    print("⚠️ Invalid index.")
                    continue
                # Generate draft with OpenAI
                prompt = (
                    f"Write a professional email response to the following message:\n\n"
                    f"Subject: {m['subject']}\n\n{m['body'] or m['snippet']}\n\n"
                    "Keep it concise and courteous. "
                    "Omit any signature or closing salutation; we will append our own."
                )
                response = openai.chat.completions.create(
                    model="gpt-4o-mini",
                    messages=[{"role": "user", "content": prompt}]
                )
                draft_body = response.choices[0].message.content.strip()
                # Append signature from config
                signature = config.get("signature_name", config.get("name", ""))
                if signature:
                    draft_body = f"{draft_body}\n\nBest regards,\n{signature}"
                last_drafts = [{
                    "to": m["from"],
                    "subject": f"Re: {m['subject']}",
                    "body": draft_body
                }]
                print(Fore.CYAN + "📝 Generated Draft:" + Style.RESET_ALL)
                print(f"To: {m['from']}\nSubject: Re: {m['subject']}\n\n{draft_body}\n")
                print("🧠 Use 'send 1' to send this draft.")
        elif task.startswith("send "):
            try:
                idx = int(task.split()[1]) - 1
                d = last_drafts[idx]
                msg_id = connector.send_email(d['to'], d['subject'], d['body'])
                print(Fore.GREEN + f"✅ Draft {idx+1} sent (Message ID: {msg_id})" + Style.RESET_ALL)
            except (IndexError, ValueError):
                print("⚠️ Invalid draft number. Use 'draft' to list and 'send <n>' to send.")
        elif task == "archive":
            # Fetch unread messages and archive them
            messages = connector.fetch_unread()
            if hasattr(connector, "archive"):
                result = connector.archive(messages)
                print(result)
            else:
                print("📦 Archive command is under development.")
        elif task == "senders":
            senders_page = 0
            show_senders_page()
        elif task == "nextsenders":
            senders_page += 1
            show_senders_page()
        elif task == "prevsenders":
            if senders_page > 0:
                senders_page -= 1
            show_senders_page()
        elif task.startswith("remove "):
            # Allow multiple comma-separated indices
            args = task[len("remove "):].strip()
            indices = [int(x.strip()) - 1 for x in args.split(",") if x.strip().isdigit()]
            if indices:
                known = config.get("known_senders", [])
                bad = config.get("bad_senders", [])
                removed = []
                # Remove in reverse order to keep indices valid
                for idx in sorted(indices, reverse=True):
                    if 0 <= idx < len(known):
                        removed_sender = known.pop(idx)
                        bad.append(removed_sender)
                        removed.append(removed_sender)
                config["known_senders"] = known
                config["bad_senders"] = bad
                with open(config_path, "w") as wf:
                    yaml.safe_dump(config, wf)
                print(f"❌ Removed and blacklisted: {removed}")
                show_senders_page()
            else:
                print("⚠️ Usage: remove <n>,<m>,... where numbers refer to the sender number on the current page.")
        elif task == "senders save":
            # Finalize and return to main menu
            senders_page = 0
            print("✅ Known senders updated and saved.")
        else:
            print("⚠️ Unknown command. Available: fetch, next, draft <n>, send <n>, archive, exit.")

